	if isTargeting then
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			local ray = camera:ViewportPointToRay(input.Position.X, input.Position.Y)
			local res = Workspace:Raycast(ray.Origin, ray.Direction * 1000)
			if res then
				targetPosition = res.Position
				local mk = Instance.new("Part")
				mk.Shape = Enum.PartType.Ball mk.Material = Enum.Material.Neon mk.Color = Color3.fromRGB(255, 0, 0) mk.Size = Vector3.new(14, 14, 14) mk.Position = targetPosition + Vector3.new(0, 5, 0) mk.Anchored = true mk.CanCollide = false mk.Parent = Workspace
