local function bigSphere(parent, pos, diameter, color, material, transparency) local p if diameter <= 2048 then p = vpart({ Shape = Enum.PartType.Ball, Size = Vector3.one * diameter, Position = pos, Color = color, Material = material, Transparency = transparency }, parent) else p = vpart({ Size = Vector3.one * 2048, Position = pos, Color = color, Material = material, Transparency = transparency }, parent) new("SpecialMesh", { MeshType = Enum.MeshType.Sphere, Scale = Vector3.one * (diameter / 2048) }, p) end return p end
local function landAt(n) return math.noise(n.X * 2.1 + 3.7, n.Y * 2.1 + 1.3, n.Z * 2.1 + 8.1) + 0.45 * math.noise(n.X * 5 + 1, n.Y * 5 + 2, n.Z * 5 + 3) > 0.04 end
local function cloudAt(n) return math.noise(n.X * 3.3 + 9.1, n.Y * 3.3 + 4.2, n.Z * 3.3 + 2.7) + 0.5 * math.noise(n.X * 8 + 5, n.Y * 8 + 6, n.Z * 8 + 7) > 0.12 end
local function plateOnSphere(folder, EC, n, r, w, color, material, transparency, thick) local p = EC + n * r return vpart({ Size = Vector3.new(w, w, thick or 2), CFrame = CFrame.lookAt(p, p + n), Color = color, Material = material or Enum.Material.SmoothPlastic, Transparency = transparency or 0 }, folder) end
local function buildStars(folder, GC) local palette = { Color3.fromRGB(190, 215, 255), Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 232, 190), Color3.fromRGB(255, 190, 140), Color3.fromRGB(160, 190, 255) } local bn = Vector3.new(0.35, 0.85, 0.4).Unit local e1 = bn:Cross(Vector3.yAxis).Unit local e2 = bn:Cross(e1).Unit local coreA = 1.2 local shell = GALAXY_RADIUS * 2.9 local detailed = false local function addStar(dir, radius, sizeScale) local s = (detailed and 12 or 18) + (math.random() ^ 3) * (detailed and 34 or 62) s *= sizeScale vpart({ Name = "DeepSpaceStar", Shape = Enum.PartType.Ball, Size = Vector3.one * s, Position = GC + dir * radius, Material = Enum.Material.Neon, Color = palette[math.random(1, #palette)], Transparency = math.random() * 0.18 }, folder) end local shellCount = detailed and 680 or 1100 for i = 1, shellCount do addStar(randDir(), shell + math.random() * GALAXY_RADIUS * 0.18, 0.8) if i % 170 == 0 then task.wait() end end local armCount = detailed and 980 or 1450 local made = 0 while made < armCount do local a = math.random() * math.pi * 2 local da = math.abs(((a - coreA + math.pi) % (math.pi * 2)) - math.pi) if math.random() < 0.35 + 0.65 * math.exp(-da * da / 0.9) then local dir = (e1 * math.cos(a) + e2 * math.sin(a) + bn * gauss() * 0.2).Unit addStar(dir, shell - GALAXY_RADIUS * 0.04 + math.random() * GALAXY_RADIUS * 0.14, 1 + 0.35 * math.exp(-da * da / 0.9)) made += 1 if made % 170 == 0 then task.wait() end end end local hazeCount = detailed and 22 or 38 local hazeColors = { Color3.fromRGB(100, 120, 255), Color3.fromRGB(255, 100, 170), Color3.fromRGB(255, 170, 90), Color3.fromRGB(110, 255, 230) } for i = 1, hazeCount do local a = math.random() * math.pi * 2 local dir = (e1 * math.cos(a) + e2 * math.sin(a) + bn * gauss() * 0.12).Unit bigSphere(folder, GC + dir * (GALAXY_RADIUS * 2.62), GALAXY_RADIUS * (0.045 + math.random() * 0.035), hazeColors[math.random(1, #hazeColors)], Enum.Material.Neon, 0.965 + math.random() * 0.025) end end
local function buildGalaxy(folder, GC) local ARMS, R = 4, GALAXY_RADIUS local textured = false local brightCount = textured and 560 or 1150 local dustCount = textured and 680 or 1050 for i = 1, brightCount do local arm = i % ARMS local tt = math.random() ^ 0.68 local r = tt * R + 120 * math.random() local ang = arm * (2 * math.pi / ARMS) + tt * 4.6 + gauss() * 0.19 * (1.2 - tt) local rr = r + gauss() * R * 0.018 * (0.4 + tt) local pos = GC + Vector3.new(math.cos(ang) * rr, 78 + gauss() * (R * 0.008 * (1 - tt) + 18), math.sin(ang) * rr) local size = (18 + math.random() * 66) * (1.1 - 0.42 * tt) local col = Color3.fromRGB(255, 225, 170):Lerp(Color3.fromRGB(255, 140, 150), clamp01(tt * 1.6)):Lerp(Color3.fromRGB(110, 150, 255), clamp01((tt - 0.5) * 2)) vpart({ Name = "GalacticArmStar", Shape = Enum.PartType.Ball, Size = Vector3.one * size, Position = pos, Material = Enum.Material.Neon, Color = col, Transparency = 0.18 + 0.47 * math.random() }, folder) if i % 130 == 0 then task.wait() end end for i = 1, dustCount do local arm = i % ARMS local tt = math.random() ^ 0.82 local ang = arm * (2 * math.pi / ARMS) + tt * 4.6 + gauss() * (textured and 0.32 or 0.25) local rr = tt * R + gauss() * R * 0.026 local pos = GC + Vector3.new(math.cos(ang) * rr, 72 + gauss() * (R * 0.006), math.sin(ang) * rr) vpart({ Name = "GalacticDustStar", Shape = Enum.PartType.Ball, Size = Vector3.one * (10 + math.random() * 25), Position = pos, Material = Enum.Material.Neon, Color = Color3.fromRGB(190, 210, 255), Transparency = 0.28 + 0.34 * math.random() }, folder) if i % 160 == 0 then task.wait() end end for i = 1, 36 do local v = Vector3.new(gauss(), gauss() * 0.35, gauss()) * (R * 0.045) bigSphere(folder, GC + v, R * (0.018 + math.random() * 0.016), Color3.fromRGB(255, 210, 145), Enum.Material.Neon, 0.945 + math.random() * 0.035) end bigSphere(folder, GC + Vector3.new(0, 88, 0), R * 0.052, Color3.fromRGB(255, 220, 150), Enum.Material.Neon, 0.56) bigSphere(folder, GC + Vector3.new(0, 92, 0), R * 0.13, Color3.fromRGB(255, 150, 90), Enum.Material.Neon, 0.945) end
local function buildEarth(folder, EC) local ER = EARTH_RADIUS local ocean = bigSphere(folder, EC, ER * 2, Color3.fromRGB(16, 64, 148), Enum.Material.SmoothPlastic, 0) ocean.Reflectance = 0.12 local landCols = { Color3.fromRGB(58, 118, 56), Color3.fromRGB(76, 132, 62), Color3.fromRGB(150, 138, 84), Color3.fromRGB(104, 92, 60), Color3.fromRGB(40, 92, 52) } local placed, tries = 0, 0 while placed < 430 and tries < 4200 do tries += 1 local n = randDir() if landAt(n) then placed += 1 local polar = math.abs(n.Y) > 0.86 local col = polar and Color3.fromRGB(238, 244, 250) or landCols[math.random(1, #landCols)] plateOnSphere(folder, EC, n, ER * 1.0015, ER * (0.065 + math.random() * 0.07), col, Enum.Material.SmoothPlastic, 0, 2) if placed % 150 == 0 then task.wait() end end end placed, tries = 0, 0 while placed < 240 and tries < 3600 do tries += 1 local n = randDir() if cloudAt(n) then placed += 1 plateOnSphere(folder, EC, n, ER * 1.014, ER * (0.12 + math.random() * 0.13), Color3.new(1, 1, 1), Enum.Material.SmoothPlastic, 0.40 + math.random() * 0.28, 1.4) if placed % 120 == 0 then task.wait() end end end bigSphere(folder, EC, ER * 2.06, Color3.fromRGB(110, 175, 255), Enum.Material.Neon, 0.88) bigSphere(folder, EC, ER * 2.13, Color3.fromRGB(110, 175, 255), Enum.Material.Neon, 0.965) return { earth = ocean, center = EC } end
local function buildMoon(folder, pos) local MR = EARTH_RADIUS * 0.29 bigSphere(folder, pos, MR * 2, Color3.fromRGB(150, 148, 144), Enum.Material.SmoothPlastic, 0) for _ = 1, 26 do local n = randDir() plateOnSphere(folder, pos, n, MR * 1.006, MR * (0.13 + math.random() * 0.3), Color3.fromRGB(96, 94, 92), Enum.Material.SmoothPlastic, 0, 0.8) end end
local function buildSolarSystem(folder, EC, GC) local radial = (EC - GC).Unit local tangent = Vector3.new(-radial.Z, 0, radial.X) if tangent.Magnitude < 0.001 then tangent = Vector3.xAxis end tangent = tangent.Unit local sunPos = EC + tangent * EARTH_ORBIT_RADIUS local e1 = -tangent local e2 = Vector3.yAxis:Cross(e1).Unit local normal = e1:Cross(e2).Unit local sun = bigSphere(folder, sunPos, SUN_RADIUS * 2, Color3.fromRGB(255, 191, 92), Enum.Material.Neon, 0) bigSphere(folder, sunPos, SUN_RADIUS * 2.09, Color3.fromRGB(255, 144, 65), Enum.Material.Neon, 0.945) bigSphere(folder, sunPos, SUN_RADIUS * 2.22, Color3.fromRGB(255, 200, 122), Enum.Material.Neon, 0.978) new("PointLight", { Color = Color3.fromRGB(255, 174, 90), Range = 60, Brightness = 5 }, sun) local planetDefs = { { name = "Mercury", orbit = 1800, radius = 18, angle = math.rad(62), color = Color3.fromRGB(156, 151, 144) }, { name = "Venus", orbit = 2550, radius = 35, angle = math.rad(137), color = Color3.fromRGB(219, 176, 113) }, { name = "Earth", orbit = EARTH_ORBIT_RADIUS, radius = EARTH_RADIUS, angle = 0, color = Color3.fromRGB(65, 145, 255) }, { name = "Mars", orbit = 4700, radius = 43, angle = math.rad(213), color = Color3.fromRGB(195, 90, 63) }, { name = "Jupiter", orbit = 6200, radius = 245, angle = math.rad(298), color = Color3.fromRGB(207, 174, 143) }, { name = "Saturn", orbit = 7550, radius = 205, angle = math.rad(158), color = Color3.fromRGB(222, 199, 145) }, { name = "Uranus", orbit = 8750, radius = 132, angle = math.rad(326), color = Color3.fromRGB(139, 215, 220) }, { name = "Neptune", orbit = 9950, radius = 124, angle = math.rad(238), color = Color3.fromRGB(75, 112, 232) } } local function orbitalPoint(distance, angle, center) center = center or sunPos return center + e1 * (math.cos(angle) * distance) + e2 * (math.sin(angle) * distance) end local function orbitLine(center, distance, segments, color, thickness, transparency, angleStart) local startAngle = angleStart or 0 local prev = orbitalPoint(distance, startAngle, center) for i = 1, segments do local a = startAngle + (i / segments) * math.pi * 2 local nextPoint = orbitalPoint(distance, a, center) local delta = nextPoint - prev local mid = (prev + nextPoint) * 0.5 vpart({ Name = "EclipticOrbitLine", Size = Vector3.new(thickness, thickness, delta.Magnitude + thickness), CFrame = CFrame.lookAt(mid, nextPoint), Color = color, Material = Enum.Material.Neon, Transparency = transparency }, folder) prev = nextPoint if i % 16 == 0 then task.wait() end end end for i, spec in ipairs(planetDefs) do local col = i == 3 and Color3.fromRGB(90, 175, 255) or Color3.fromRGB(119, 145, 174) orbitLine(sunPos, spec.orbit, 36, col, math.max(1.1, spec.orbit * 0.00025), i == 3 and 0.40 or 0.68, 0) end for _, spec in ipairs(planetDefs) do if spec.name ~= "Earth" then local pos = orbitalPoint(spec.orbit, spec.angle) local body = bigSphere(folder, pos, spec.radius * 2, spec.color, Enum.Material.SmoothPlastic, 0) if spec.name == "Venus" then bigSphere(folder, pos, spec.radius * 2.09, Color3.fromRGB(255, 194, 113), Enum.Material.Neon, 0.95) elseif spec.name == "Mars" then bigSphere(folder, pos, spec.radius * 2.10, Color3.fromRGB(255, 103, 75), Enum.Material.Neon, 0.95) elseif spec.name == "Saturn" then for j = 1, 4 do local colors = { Color3.fromRGB(218, 199, 160), Color3.fromRGB(146, 125, 96), Color3.fromRGB(232, 215, 180), Color3.fromRGB(105, 93, 77) } orbitLine(pos, spec.radius * (1.34 + j * 0.19), 40, colors[j], 3.4 + (j % 2), 0.22 + (j % 2) * 0.10, math.rad(j * 4)) end elseif spec.name == "Jupiter" then for j = 1, 20 do local n = randDir() local band = (j % 3 == 0) and Color3.fromRGB(153, 105, 82) or Color3.fromRGB(238, 211, 175) plateOnSphere(folder, pos, n, spec.radius * 1.006, spec.radius * (0.06 + math.random() * 0.1), band, Enum.Material.SmoothPlastic, 0.20 + math.random() * 0.18, 2) end end end end for i = 1, 105 do local a = math.random() * math.pi * 2 local r = 5480 + math.random() * 460 local pos = sunPos + e1 * (math.cos(a) * r) + e2 * (math.sin(a) * r) + normal * gauss() * 160 local size = 7 + math.random() * 23 vpart({ Name = "AsteroidBeltRock", Size = Vector3.new(size * (0.65 + math.random() * 0.75), size * (0.5 + math.random() * 0.6), size * (0.65 + math.random() * 0.8)), CFrame = CFrame.new(pos) * CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6), Color = Color3.fromRGB(77 + math.random(0, 35), 73 + math.random(0, 28), 70 + math.random(0, 24)), Material = Enum.Material.Slate }, folder) if i % 35 == 0 then task.wait() end end return { sun = sun, sunPos = sunPos, sunDir = (sunPos - EC).Unit, earthOrbit = EARTH_ORBIT_RADIUS, normal = normal } end
local function buildCannon(folder, cf) local SCALE = 40 local C = { coils = {}, coilGlow = {}, railSegments = {}, moving = {}, navLights = {}, arcBeams = {}, emitterParts = {} } local model = new("Model", { Name = "OriginalStyleStarDestroyer" }, folder) model.WorldPivot = cf C.model = model C.baseCF = cf local root = model local HULL = Color3.fromRGB(28, 31, 39) local HULL_LIT = Color3.fromRGB(48, 52, 62) local METAL = Color3.fromRGB(129, 136, 148) local METAL_DARK = Color3.fromRGB(68, 74, 86) local DARK = Color3.fromRGB(14, 17, 23) local GOLD = Color3.fromRGB(191, 148, 62) local GOLD_LIT = Color3.fromRGB(255, 205, 112) local RED_OFF = Color3.fromRGB(72, 12, 20) local RED = Color3.fromRGB(235, 28, 42) local HOT = Color3.fromRGB(255, 225, 218) local function L(x, y, z) return Vector3.new(x * SCALE, y * SCALE, z * SCALE) end local function cfL(x, y, z, rz, ry, rx) return CFrame.new(L(x, y, z)) * CFrame.Angles(rx or 0, ry or 0, rz or 0) end local function box(name, x, y, z, sx, sy, sz, col, mat, rz, ry, rx, transparency) return vpart({ Name = name or "CannonPanel", Size = L(sx, sy, sz), Color = col or HULL, Material = mat or Enum.Material.Metal, Transparency = transparency or 0, CFrame = cf * cfL(x, y, z, rz, ry, rx) }, root) end local function axialCylinder(name, z, radius, length, col, mat, transparency) return vpart({ Name = name or "AxialCylinder", Shape = Enum.PartType.Cylinder, Size = Vector3.new(length * SCALE, radius * 2 * SCALE, radius * 2 * SCALE), Color = col or HULL, Material = mat or Enum.Material.Metal, Transparency = transparency or 0, CFrame = cf * CFrame.new(0, 0, z * SCALE) * CFrame.Angles(0, math.rad(90), 0) }, root) end local function sphere(name, x, y, z, radius, col, mat, transparency) return vpart({ Name = name or "CannonCore", Shape = Enum.PartType.Ball, Size = Vector3.one * (radius * 2 * SCALE), Position = (cf * CFrame.new(L(x, y, z))).Position, Color = col or HULL, Material = mat or Enum.Material.Metal, Transparency = transparency or 0 }, root) end local function octRing(name, z, outer, inner, thickness, col, mat, targetList, transparency) local parts = {} for i = 0, 7 do local a = i * math.pi / 4 local mid = (outer + inner) * 0.5 local tangential = 2 * outer * math.tan(math.pi / 8) * 1.04 parts[#parts + 1] = box(name, math.cos(a) * mid, math.sin(a) * mid, z, outer - inner, tangential, thickness, col, mat, a, 0, 0, transparency) end if targetList then targetList[#targetList + 1] = parts end return parts end local function octLine(name, z, radius, width, col, targetList, transparency) local parts = {} local outer = radius + width * 0.5 local inner = radius - width * 0.5 for i = 0, 7 do local a = i * math.pi / 4 local mid = (outer + inner) * 0.5 local tangential = 2 * radius * math.tan(math.pi / 8) * 1.08 parts[#parts + 1] = box(name, math.cos(a) * mid, math.sin(a) * mid, z, width, tangential, math.max(width * 0.75, 0.025), col, Enum.Material.Neon, a, 0, 0, transparency or 0.2) end if targetList then targetList[#targetList + 1] = parts end return parts end local function barBetween(name, a, b, width, depth, col, mat) local p0 = cf:PointToWorldSpace(L(a.X, a.Y, a.Z)) local p1 = cf:PointToWorldSpace(L(b.X, b.Y, b.Z)) local delta = p1 - p0 local mid = (p0 + p1) * 0.5 return vpart({ Name = name or "CannonStrut", Size = Vector3.new(width * SCALE, depth * SCALE, delta.Magnitude), Color = col or METAL_DARK, Material = mat or Enum.Material.Metal, CFrame = CFrame.lookAt(mid, p1) }, root) end local function ringDots(name, z, radius, count, dotRadius, col, mat, targetList) local list = {} for i = 0, count - 1 do local a = i * math.pi * 2 / count list[#list + 1] = sphere(name, math.cos(a) * radius, math.sin(a) * radius, z, dotRadius, col, mat) end if targetList then targetList[#targetList + 1] = list end return list end C.recoilPart = box("InternalRecoilAnchor", 0, 0, -3.1, 0.01, 0.01, 0.01, HULL, Enum.Material.SmoothPlastic, 0, 0, 0, 1) axialCylinder("OctagonalBarrelCore", -6.3, 0.64, 19.2, HULL, Enum.Material.Metal) for i = 0, 7 do local a = i * math.pi / 4 box("BarrelArmorFacet", math.cos(a) * 0.55, math.sin(a) * 0.55, -6.25, 0.28, 0.44, 18.8, HULL_LIT, Enum.Material.Metal, a) box("BarrelPanelSeam", math.cos(a) * 0.693, math.sin(a) * 0.693, -6.2, 0.035, 0.06, 17.8, METAL_DARK, Enum.Material.Metal, a) end for k = 0, 16 do local z = -14.5 + k * 1.05 local heavy = (k % 4 == 0) local outer = heavy and 1.62 or 1.38 local axial = heavy and 0.24 or 0.11 local main = octRing("InductionCoilHousing", z, outer, 1.0, axial, k % 4 == 0 and METAL or METAL_DARK, Enum.Material.Metal) local innerGlow = octLine("CoilInnerFluxTrack", z, 1.045, 0.045, RED_OFF, nil, 0.2) local grooveGlow = octLine("CoilOuterFluxGroove", z, heavy and 1.30 or 1.20, 0.035, RED_OFF, nil, 0.35) local clamps = {} if heavy then for i = 0, 7 do local a = i * math.pi / 4 clamps[#clamps + 1] = box("CoilClamp", math.cos(a) * (outer + 0.10), math.sin(a) * (outer + 0.10), z, 0.19, 0.26, 0.40, METAL, Enum.Material.Metal, a) end end C.coils[#C.coils + 1] = { z = z, main = main, inner = innerGlow, groove = grooveGlow, clamps = clamps, k = k, heavy = heavy } end for _, sy in ipairs({ -1, 1 }) do box("UpperLowerGuideRail", 0, sy * 0.80, -6.55, 0.60, 0.32, 19.9, METAL_DARK, Enum.Material.Metal) box("GuideRailInset", 0, sy * 0.80 + sy * 0.13, -6.55, 0.18, 0.07, 19.4, RED_OFF, Enum.Material.Neon, 0, 0, 0, 0.28) end for _, sx in ipairs({ -1, 1 }) do for _, sy in ipairs({ -1, 1 }) do local conduit = axialCylinder("PowerConduit", -5.8, 0.075, 18.4, METAL_DARK, Enum.Material.Metal) conduit.CFrame = cf * CFrame.new(sx * 1.5 * SCALE, sy * 0.52 * SCALE, -5.8 * SCALE) * CFrame.Angles(0, math.rad(90), 0) local railParts = {} for k = 0, 16 do local z = -14.6 + k * 1.05 railParts[#railParts + 1] = box("SequentialPowerRail", sx * 1.5, sy * 0.52, z, 0.095, 0.095, 0.68, RED_OFF, Enum.Material.Neon, 0, 0, 0, 0.26) end C.railSegments[#C.railSegments + 1] = { sideX = sx, sideY = sy, parts = railParts } end end for i = 0, 7 do local a = i * math.pi / 4 local x, y = math.cos(a), math.sin(a) barBetween("BarrelTrussLongitudinal", Vector3.new(x * 1.90, y * 1.90, -15.2), Vector3.new(x * 1.90, y * 1.90, 3.2), 0.075, 0.075, DARK) for k = 0, 16 do local z = -14.5 + k * 1.05 local r = 1.84 box("TrussCrossBrace", math.cos(a) * r, math.sin(a) * r, z, 0.07, 0.07, 0.15, METAL_DARK, Enum.Material.Metal, a) end end local muzzleRing = octRing("MuzzleArmorCollar", -16.1, 1.55, 0.62, 0.90, HULL_LIT, Enum.Material.Metal) octRing("MuzzleForwardBezel", -16.36, 1.31, 0.62, 0.20, METAL_DARK, Enum.Material.Metal) octLine("MuzzleRedAnnulus", -16.20, 1.24, 0.055, RED_OFF, nil, 0.12) axialCylinder("MuzzleLensHousing", -15.75, 0.60, 0.20, DARK, Enum.Material.Metal) local lens = axialCylinder("ChargingLens", -15.87, 0.49, 0.035, RED, Enum.Material.Neon, 0.06) C.lens = lens for i = 0, 15 do local a = i * math.pi * 2 / 16 local r = 1.47 box("MuzzleVent", math.cos(a) * r, math.sin(a) * r, -16.1, 0.11, 0.07, 0.34, DARK, Enum.Material.Metal, a) end for i = 0, 5 do local a = i * math.pi / 3 + math.pi / 6 local function prongPiece(z, rad, width, depth, length, tone) return box("SixClawEmitterProng", math.cos(a) * rad, math.sin(a) * rad, z, width, depth, length, tone, Enum.Material.Metal, a) end prongPiece(-17.10, 1.00, 0.17, 0.23, 1.45, METAL_DARK) prongPiece(-18.40, 0.79, 0.10, 0.16, 1.30, METAL) local line = box("ClawEmitterRedLine", math.cos(a) * 0.91, math.sin(a) * 0.91, -18.10, 0.035, 0.04, 1.75, RED_OFF, Enum.Material.Neon, a, 0, 0, 0.15) C.emitterParts[#C.emitterParts + 1] = line end ringDots("MuzzleTipMicroSegments", -19.08, 0.70, 24, 0.048, METAL, Enum.Material.Metal) ringDots("MuzzleTipFluxSegments", -19.10, 0.62, 24, 0.026, RED_OFF, Enum.Material.Neon) C.muzzleCF = cf * CFrame.new(0, 0, -19.2 * SCALE) for i = 0, 7 do local a = i * math.pi / 4 box("RearOctagonalBodyPanel", math.cos(a) * 1.46, math.sin(a) * 1.46, 5.75, 0.56, 1.12, 4.4, HULL_LIT, Enum.Material.Metal, a) end axialCylinder("RearBodyCore", 5.75, 1.82, 4.8, HULL, Enum.Material.Metal) octRing("RearBodyHexFlange", 3.35, 1.5, 0.50, 0.40, METAL, Enum.Material.Metal) octRing("RearGoldSeal", 6.92, 2.00, 1.82, 0.36, GOLD, Enum.Material.Metal) octRing("RearArmorPlate", 12.0, 2.2, 0.45, 0.44, HULL_LIT, Enum.Material.Metal) axialCylinder("ReactorCoreMount", 10.0, 1.05, 1.8, DARK, Enum.Material.Metal) local core = sphere("ReactorGoldCore", 0, 0, 10.0, 1.05, GOLD, Enum.Material.Metal) core.Reflectance = 0.22 C.reactor = core ringDots("ReactorTorusGold", 10.0, 1.75, 28, 0.21, GOLD_LIT, Enum.Material.Metal) for i = 0, 5 do local a = i * math.pi / 3 barBetween("ReactorRadialSupport", Vector3.new(math.cos(a) * 1.2, math.sin(a) * 1.2, 10.0), Vector3.new(math.cos(a) * 2.35, math.sin(a) * 2.35, 10.0), 0.11, 0.11, DARK) end box("CommandBridge", 0, 2.30, 5.10, 1.44, 0.96, 2.70, DARK, Enum.Material.Metal) box("CommandBridgeGlass", 0, 2.78, 5.10, 1.12, 0.055, 2.08, Color3.fromRGB(110, 190, 215), Enum.Material.Glass, 0, 0, 0, 0.32) for _, sx in ipairs({ -1, 1 }) do box("BridgeFrameRail", sx * 0.82, 2.35, 5.10, 0.12, 1.42, 2.55, METAL_DARK, Enum.Material.Metal) end for _, sx in ipairs({ -1, 1 }) do for _, yy in ipairs({ -0.74, 0, 0.74 }) do local cap = axialCylinder("BodyCoolingCanister", 5.6, 0.30, 4.05, METAL_DARK, Enum.Material.Metal) cap.CFrame = cf * CFrame.new(sx * 2.55 * SCALE, yy * SCALE, 5.6 * SCALE) * CFrame.Angles(0, math.rad(90), 0) for rib = -2, 2 do local band = axialCylinder("CoolingCanisterRib", 5.6 + rib * 0.62, 0.335, 0.10, METAL, Enum.Material.Metal) band.CFrame = cf * CFrame.new(sx * 2.55 * SCALE, yy * SCALE, (5.6 + rib * 0.62) * SCALE) * CFrame.Angles(0, math.rad(90), 0) end end end for _, z in ipairs({ 4.6, 6.9, 12.0 }) do for i = 0, 7 do local a = i * math.pi / 4 box("ArmorSeam", math.cos(a) * 1.93, math.sin(a) * 1.93, z, 0.035, 0.05, 0.045, METAL, Enum.Material.Metal, a) end end for i = 0, 3 do local a = math.pi / 4 + i * math.pi / 2 box("RadiatorOuterSpine", math.cos(a) * 5.15, math.sin(a) * 5.15, 8.1, 0.14, 0.14, 7.1, METAL_DARK, Enum.Material.Metal, a) box("RadiatorInnerSpine", math.cos(a) * 2.72, math.sin(a) * 2.72, 8.1, 0.16, 0.16, 6.8, DARK, Enum.Material.Metal, a) for _, side in ipairs({ -1, 1 }) do box("RadiatorSideFrame", math.cos(a) * 5.15 - math.sin(a) * side * 2.42, math.sin(a) * 5.15 + math.cos(a) * side * 2.42, 8.1, 4.9, 0.12, 0.14, DARK, Enum.Material.Metal, a) end for j = 0, 13 do local z = 4.85 + j * 0.50 local slat = box("RadiatorThermalSlat", math.cos(a) * 5.15, math.sin(a) * 5.15, z, 4.75, 0.045, 0.34, j % 3 == 0 and METAL_DARK or Color3.fromRGB(91, 95, 102), Enum.Material.Metal, a) if j % 3 == 0 then local hotLine = box("RadiatorHeatTrace", math.cos(a) * 5.15, math.sin(a) * 5.15, z, 4.3, 0.018, 0.035, RED_OFF, Enum.Material.Neon, a, 0, 0, 0.45) C.emitterParts[#C.emitterParts + 1] = hotLine end end end for face = 0, 7 do local a = face * math.pi / 4 local ux, uy = math.cos(a), math.sin(a) for k = 0, 15 do local z = -13.95 + k * 1.05 box("InductionRailArmorLink", ux * 1.47, uy * 1.47, z, 0.095, 0.19, 0.44, k % 4 == 0 and METAL or HULL_LIT, Enum.Material.Metal, a) if k % 2 == 0 then box("InductionRailFastener", ux * 1.57, uy * 1.57, z, 0.065, 0.065, 0.09, GOLD, Enum.Material.Metal, a) end end end for face = 0, 5 do local a = face * math.pi / 3 + math.pi / 6 local ux, uy = math.cos(a), math.sin(a) box("ReactorArmorShoulder", ux * 2.34, uy * 2.34, 8.55, 0.42, 1.08, 3.05, HULL_LIT, Enum.Material.Metal, a) box("ReactorShoulderGoldInlay", ux * 2.58, uy * 2.58, 8.55, 0.045, 0.76, 2.28, GOLD, Enum.Material.Metal, a) for rib = 0, 2 do box("ReactorShoulderVent", ux * 2.64, uy * 2.64, 7.82 + rib * 0.72, 0.055, 0.22, 0.10, DARK, Enum.Material.Metal, a) end end for _, sx in ipairs({ -1, 1 }) do local col = sx < 0 and Color3.fromRGB(255, 48, 56) or Color3.fromRGB(50, 255, 140) local nav = sphere("NavigationBeacon", sx * 7.68, 0, 8.1, 0.12, col, Enum.Material.Neon) local pl = new("PointLight", { Color = col, Range = 110, Brightness = 0.55 }, nav) C.navLights[#C.navLights + 1] = { part = nav, light = pl, base = col, side = sx } end for i = 0, 5 do local a = i * math.pi / 3 local p = box("RearGantryArm", math.cos(a) * 2.7, math.sin(a) * 2.7, -1.3, 0.18, 0.18, 13.8, METAL_DARK, Enum.Material.Metal, a) C.moving[#C.moving + 1] = { part = p, localCF = cfL(math.cos(a) * 2.7, math.sin(a) * 2.7, -1.3, a), phase = a } end local chargeOrb = sphere("ChargeSingularity", 0, 0, -17.4, 0.12, RED, Enum.Material.Neon) C.orb = chargeOrb C.orbLight = new("PointLight", { Color = RED, Range = 110, Brightness = 0.2 }, chargeOrb) local centerAtt = new("Attachment", { Name = "ChargeCoreAttachment", Position = Vector3.zero }, chargeOrb) C.reactorLight = new("PointLight", { Color = GOLD_LIT, Range = 180, Brightness = 0.6 }, core) local lastDetailUpdate = -1e9 local lastX = -1 local lastRecoil = -1e9 function C.update(x, t) x = clamp01(x or 0) local pulse = 0.5 + 0.5 * math.sin(t * (30 + x * 42)) local front = 3.4 - 19.8 * clamp01(x * 2) local recoil = t >= T.fireT and (1.4 * (1 - math.exp(-math.max(t - T.fireT, 0) * 14)) * math.exp(-math.max(t - T.fireT, 0) * 0.8)) or 0 if math.abs(recoil - lastRecoil) > 0.002 then model:PivotTo(cf * CFrame.new(0, 0, recoil * SCALE)) lastRecoil = recoil end C.muzzleCF = cf * CFrame.new(0, 0, (-19.2 + recoil) * SCALE) local updateDetails = (t - lastDetailUpdate) > 0.045 or math.abs(x - lastX) > 0.012 if updateDetails then lastDetailUpdate = t lastX = x for _, c in ipairs(C.coils) do local z = c.z local wave = math.exp(-((z - front) / 0.7) ^ 2) local lit = smooth(clamp01((z - front + 0.3) / 0.9)) * clamp01(x * 2) local awake = 0.08 + 0.10 * (0.5 + 0.5 * math.sin(t * 2 + c.k * 0.32)) local glow = clamp01(awake + lit * 0.72 + wave * 0.7 + (t >= T.fireT and 0.5 * math.exp(-(t - T.fireT) * 5) or 0)) local tone = METAL_DARK:Lerp(METAL, 0.25 + glow * 0.70) for _, p in ipairs(c.main) do p.Color = tone end for _, p in ipairs(c.inner) do p.Color = RED:Lerp(HOT, clamp01(wave * 0.75 + lit * 0.4)) p.Transparency = 0.56 - 0.50 * glow end for _, p in ipairs(c.groove) do p.Color = RED:Lerp(HOT, clamp01(wave * 0.88 + lit * 0.26)) p.Transparency = 0.72 - 0.63 * clamp01(wave + lit * 0.6) end for _, p in ipairs(c.clamps) do p.Color = METAL_DARK:Lerp(GOLD_LIT, clamp01(wave * 0.24 + lit * 0.12)) end end for _, railGroup in ipairs(C.railSegments) do for _, p in ipairs(railGroup.parts) do local localZ = cf:PointToObjectSpace(p.Position).Z / SCALE local wave = math.exp(-((localZ - front) / 0.95) ^ 2) local lit = smooth(clamp01((localZ - front + 0.3) / 1.0)) * clamp01(x * 2) p.Color = RED:Lerp(HOT, clamp01(wave * 0.95 + lit * 0.24)) p.Transparency = 0.76 - 0.65 * clamp01(wave + lit * 0.8) end end for _, p in ipairs(C.emitterParts) do p.Color = RED:Lerp(HOT, clamp01(x * 0.75 + pulse * 0.2)) p.Transparency = 0.38 - 0.30 * x end end local radius = 0.12 + x ^ 1.2 * 1.55 * (0.9 + 0.1 * pulse) C.orb.Size = Vector3.one * (radius * 2 * SCALE) C.orb.Color = RED:Lerp(HOT, clamp01(x * x * 0.9 + pulse * x * 0.2)) C.orbLight.Brightness = 0.2 + x * x * 12 C.orbLight.Range = 45 + x * 190 C.lens.Color = RED:Lerp(HOT, clamp01(x * 0.95 + pulse * x * 0.15)) C.lens.Transparency = 0.28 - 0.24 * x C.reactorLight.Brightness = 0.4 + 1.8 * x end return C end
local function buildStage(stage) local folder = new("Folder", { Name = "SpaceStage" }, Workspace) stage.folder = folder local GC = SPACE_ORIGIN local CP = GC + Vector3.new(18000, 1200, 9000) local fwd = Vector3.new(-0.78, -0.02, -0.2).Unit local cannonCF = CFrame.lookAt(CP, CP + fwd) local EC = CP + fwd * 5200 + cannonCF.RightVector * -500 + cannonCF.UpVector * -150 stage.GC, stage.CP, stage.cannonCF, stage.EC = GC, CP, cannonCF, EC local nT = (CP - EC).Unit stage.nT = nT stage.markPt = EC + nT * EARTH_RADIUS stage.cannon = buildCannon(folder, cannonCF) task.wait(0.5) buildGalaxy(folder, GC) task.wait(0.5) buildStars(folder, GC) task.wait(0.5) stage.earthSurface = buildEarth(folder, EC) task.wait(0.5) stage.solarSystem = buildSolarSystem(folder, EC, GC) task.wait(0.5) stage.sunPos, stage.sunDir = stage.solarSystem.sunPos, stage.solarSystem.sunDir buildMoon(folder, EC + Vector3.new(220, 160, 420)) task.wait(0.5) for _ = 1, 70 do local off = Vector3.new(gauss(), gauss() * 0.6, gauss()) * 1500 if off.Magnitude > 450 then vpart({ Size = Vector3.new(14 + math.random() * 70, 14 + math.random() * 50, 14 + math.random() * 70), Material = Enum.Material.Slate, Color = Color3.fromRGB(70, 66, 70), CFrame = CFrame.new(CP + off) * CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6) }, folder) end end stage.ready = true end
local function finishCinematic(stage, conn) if conn then conn:Disconnect() end if stage and stage.folder then stage.folder:Destroy() end clearFx() showBars(false) setCaption("") camera.CameraType = Enum.CameraType.Custom camera.FieldOfView = 70 setControls(true) setCoreGui(true) setFlash(0) state = "idle" end
local function runSequence(target) state = "cinematic" lastFire = os.clock() local startCF = camera.CFrame local startFov = camera.FieldOfView local startPos = startCF.Position local imp = T.imp camera.CameraType = Enum.CameraType.Scriptable setControls(false) setCoreGui(false) showBars(true) ensureFx() setFlash(1) setCaption("正在构建宇宙模型，请稍候...", Color3.fromRGB(255, 255, 255)) local stage = { ready = false } task.spawn(function() buildStage(stage) end) local timeout = tick() + 15 while not stage.ready and tick() < timeout do task.wait(0.1) end setFlash(0) if not stage.ready then stage.ready = true end setCaption("目标锁定  ·  TARGET LOCKED", Color3.fromRGB(255, 120, 120)) local t0 = os.clock() local conn local finished = false conn = RunService.RenderStepped:Connect(function() if finished then return end local t = os.clock() - t0 if t >= T.endT then finished = true finishCinematic(stage, conn) return end local cf local fov = 70 local shakeAmp, rotAmp = 0, 0 local f = 0 if t < T.groundT then if not stage.finished then stage.finished = true end local u = clamp01((t - T.lockEnd) / (T.ascentEnd - T.lockEnd)) local h = 40 * ((14000 / 40) ^ u - 1) local eo = smooth(u) local pos = Vector3.new(startPos.X + (target.X - startPos.X) * eo * 0.9, startPos.Y + h, startPos.Z + (target.Z - startPos.Z) * eo * 0.9) local rot = startCF.Rotation:Lerp(CFrame.lookAt(Vector3.zero, Vector3.new(0, -1, 0), Vector3.new(0, 0, -1)), smooth(clamp01((u - 0.1) / 0.9))) cf = CFrame.new(pos) * rot fov = startFov + (55 - startFov) * u fx.blur.Size = 22 * clamp01((t - (T.ascentEnd - 1.2)) / 1.2) fx.cc.Brightness = -0.05 * u fx.cc.Saturation = 0.2 * u if t >= T.ascentEnd then fov = 70 cf = CFrame.lookAt(target + Vector3.new(0, 1000, 0), target) f = math.max(f, pulseWin(t, T.fireT, 0.02, 0.9)) shakeAmp = 16 * math.exp(-(t - T.fireT) * 1.6) rotAmp = 0.012 * math.exp(-(t - T.fireT) * 1.6) fov = 70 + 20 * math.exp(-(t - T.fireT) * 4) end else local g = t - T.groundT local ang = math.max(0, t - imp) * 0.06 local offs = CFrame.Angles(0, ang, 0) * (Vector3.new(math.cos(math.atan2(startCF.LookVector.Z, startCF.LookVector.X) + math.pi), 0, math.sin(math.atan2(startCF.LookVector.Z, startCF.LookVector.X) + math.pi)) * 520 + Vector3.new(0, 170, 0)) * (1 - 0.08 * clamp01(g / (imp - T.groundT))) cf = CFrame.lookAt(target + offs, target + Vector3.new(0, 45, 0)) fov = 70 + (62 - 70) * clamp01(g / 6) f = math.max(f, (t > T.groundT - 0.01 and t < T.groundT + 0.8) and (1 - (t - T.groundT) / 0.8) or 0) end f = math.max(f, impactFlashValue()) local ia = impactShakeAmount() shakeAmp += ia rotAmp += ia * 0.0015 if t > T.endT - 0.8 then setFlash(clamp01((t - (T.endT - 0.8)) / 0.8), Color3.new(0, 0, 0)) else setFlash(f) end camera.FieldOfView = fov camera.CFrame = shakeCF(cf, shakeAmp, t, rotAmp) end) end _G.TriggerStarDestroyer = runSequence
